style.css:
@-moz-document domain("youtube.com") {
/* colour palette */
:root {
  --my-night: #171827;
  --my-deep: #202137;
  --my-card: #282940;
  --my-lavender: #aaa3c8;
  --my-mauve: #b99aaa;
  --my-silver: #e5e1ed;
  --my-muted: #aaa6bb;
  --my-border: #38374f;

  --yt-spec-base-background: #171827 !important;
  --yt-spec-raised-background: #202137 !important;
  --yt-spec-menu-background: #202137 !important;
  --yt-spec-text-primary: #e5e1ed !important;
  --yt-spec-text-secondary: #aaa6bb !important;
  --yt-spec-call-to-action: #aaa3c8 !important;
}

/* main background */
html,
body,
ytd-app,
#content {
  background: var(--my-night) !important;
  color: var(--my-silver) !important;
}

/* top navigation */
#masthead-container,
ytd-masthead,
#background.ytd-masthead {
  background: var(--my-night) !important;
}

/* sidebar */
#guide,
ytd-guide-renderer,
ytd-mini-guide-renderer,
#guide-content {
  background: var(--my-night) !important;
}

ytd-guide-entry-renderer,
ytd-mini-guide-entry-renderer {
  color: var(--my-silver) !important;
}

/* sidebar hover */
ytd-guide-entry-renderer:hover {
  background: var(--my-deep) !important;
  border-radius: 12px !important;
}

/* search bar */
#container.ytd-searchbox {
  background: var(--my-deep) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 24px !important;
}

#search,
ytd-searchbox input {
  color: var(--my-silver) !important;
}

/* search button */
#search-icon-legacy {
  background: var(--my-card) !important;
  color: var(--my-lavender) !important;
  border-radius: 0 24px 24px 0 !important;
}

/* category buttons */
yt-chip-cloud-chip-renderer,
ytd-feed-filter-chip-bar-renderer {
  border-radius: 20px !important;
}

yt-chip-cloud-chip-renderer[chip-style="STYLE_DEFAULT"] {
  background: var(--my-deep) !important;
  color: var(--my-silver) !important;
}

/* video cards */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer {
  border-radius: 14px !important;
}

/* video thumbnails */
ytd-thumbnail,
ytd-thumbnail img,
#thumbnail {
  border-radius: 12px !important;
  overflow: hidden !important;
}

/* video titles */
#video-title,
.yt-lockup-metadata-view-model__title {
  color: var(--my-silver) !important;
}

/* secondary text */
#metadata-line,
.ytd-video-meta-block,
#channel-name,
.ytd-channel-name {
  color: var(--my-muted) !important;
}

/* buttons */
yt-button-shape button,
ytd-button-renderer button {
  border-radius: 20px !important;
}

/* lavender hover */
a:hover,
#video-title:hover {
  color: var(--my-lavender) !important;
}

/* menus and popups */
ytd-popup-container,
tp-yt-paper-dialog,
ytd-menu-popup-renderer {
  background: var(--my-deep) !important;
  color: var(--my-silver) !important;
}

/* separators */
ytd-guide-renderer hr,
#separator {
  border-color: var(--my-border) !important;
}

/* scrollbars */
::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-thumb {
  background: var(--my-lavender) !important;
  border-radius: 10px !important;
}

/* text selection */
::selection {
  background: var(--my-lavender) !important;
  color: var(--my-night) !important;
}
}
